static int call_legacy_cert_cb1(gnutls_session_t session,
				const struct gnutls_cert_retr_st *info,
				gnutls_pcert_st **certs,
				unsigned int *pcert_length,
				gnutls_ocsp_data_st **ocsp,
				unsigned int *ocsp_length,
				gnutls_privkey_t *privkey, unsigned int *flags)
{
	gnutls_retr2_st st2;
	gnutls_pcert_st *local_certs = NULL;
	gnutls_privkey_t local_key = NULL;
	unsigned i;
	int ret;

	*ocsp_length = 0;

	memset(&st2, 0, sizeof(st2));

	ret = info->cred->legacy_cert_cb1(session, info->req_ca_rdn,
					  info->nreqs, info->pk_algos,
					  info->pk_algos_length, &st2);
	if (ret < 0)
		return gnutls_assert_val(ret);

	if (st2.ncerts == 0) {
		*pcert_length = 0;
		*ocsp_length = 0;
		*privkey = NULL;
		return 0;
	}

	if (st2.cert_type != GNUTLS_CRT_X509) {
		gnutls_assert();
		ret = GNUTLS_E_INVALID_REQUEST;
		goto cleanup;
	}

	local_certs = alloc_and_load_x509_certs(st2.cert.x509, st2.ncerts);
	if (local_certs == NULL) {
		gnutls_assert();
		ret = GNUTLS_E_MEMORY_ERROR;
		goto cleanup;
	}

	switch (st2.key_type) {
#ifdef ENABLE_PKCS11
	case GNUTLS_PRIVKEY_PKCS11:
		if (st2.key.pkcs11 != NULL) {
			local_key = alloc_and_load_pkcs11_key(st2.key.pkcs11,
							      st2.deinit_all);
			if (local_key == NULL) {
				gnutls_assert();
				ret = GNUTLS_E_INTERNAL_ERROR;
				goto cleanup;
			}
		}
		break;
#endif
	case GNUTLS_PRIVKEY_X509:
		if (st2.key.x509 != NULL) {
			local_key = alloc_and_load_x509_key(st2.key.x509,
							    st2.deinit_all);
			if (local_key == NULL) {
				gnutls_assert();
				ret = GNUTLS_E_INTERNAL_ERROR;
				goto cleanup;
			}
		}
		break;
	default:
		gnutls_assert();
		ret = GNUTLS_E_INVALID_REQUEST;
		goto cleanup;

		zrelease_mpi_key(&session->key.proto.tls12.ecdh.y);
		_gnutls_free_key_datum(&session->key.proto.tls12.ecdh.raw);

		zrelease_mpi_key(&session->key.proto.tls12.dh.client_Y);

		/* SRP */
		zrelease_mpi_key(&session->key.proto.tls12.srp.srp_p);
		zrelease_mpi_key(&session->key.proto.tls12.srp.srp_g);
		zrelease_mpi_key(&session->key.proto.tls12.srp.srp_key);

		zrelease_mpi_key(&session->key.proto.tls12.srp.u);
		zrelease_mpi_key(&session->key.proto.tls12.srp.a);
		zrelease_mpi_key(&session->key.proto.tls12.srp.x);
		zrelease_mpi_key(&session->key.proto.tls12.srp.A);
		zrelease_mpi_key(&session->key.proto.tls12.srp.B);
		zrelease_mpi_key(&session->key.proto.tls12.srp.b);
	} else {
		gnutls_memset(session->key.proto.tls13.temp_secret, 0,
			      sizeof(session->key.proto.tls13.temp_secret));
	}

	reset_binders(session);
	_gnutls_free_key_datum(&session->key.key);
}

