+	gnutls_certificate_credentials_t cred)
+{
+	cert_comp_cache_st *cache = &cred->cert_comp_cache;
+	unsigned i;
+
+	if (cache->lock == NULL)
+		return;
+
+	gnutls_mutex_lock(&cache->lock);
+	for (i = 0; i < GNUTLS_CERT_COMP_CACHE_ENTRIES; i++)
