   126		CHECK(gnutls_credentials_set(session, GNUTLS_CRD_CERTIFICATE,
   127					     x509_cred));
   128		CHECK(gnutls_priority_set_direct(session, PRIO, NULL));
   129		CHECK(gnutls_compress_certificate_set_methods(
   130			session, methods, sizeof(methods) / sizeof(methods[0])));
   131	
   132		gnutls_session_set_ptr(session, &compressed);
   133		gnutls_handshake_set_hook_function(
   134			session, GNUTLS_HANDSHAKE_COMPRESSED_CERTIFICATE_PKT,
   135			GNUTLS_HOOK_PRE, compressed_cert_callback);
   136		gnutls_transport_set_int(session, fd);
   137	
   138		do {
   139			ret = gnutls_handshake(session);
   140		} while (ret < 0 && gnutls_error_is_fatal(ret) == 0);
   141		if (ret < 0)
   142			fail("server: handshake failed: %s\n", gnutls_strerror(ret));
   143	
   144		if (gnutls_compress_certificate_get_selected_method(session) !=
   145		    GNUTLS_COMP_ZLIB)
   146			fail("server: zlib certificate compression was not selected\n");
   147	
   148		gnutls_bye(session, GNUTLS_SHUT_WR);
   149		close(fd);
   150		gnutls_deinit(session);
   151	}
   152	
   153	void doit(void)
   154	{
   155		int ret;
   156		int fd[2];
   157		unsigned round;
   158		gnutls_certificate_credentials_t server_cred;
   159	
   160		signal(SIGPIPE, SIG_IGN);
   161		CHECK(gnutls_global_init());
   162		gnutls_global_set_log_function(log_func);
   163		gnutls_global_set_log_level(4);
   164	
   165		CHECK(gnutls_certificate_allocate_credentials(&server_cred));
   166		CHECK(gnutls_certificate_set_x509_key_mem(
   167			server_cred, &server_ca3_localhost_cert_chain,
   168			&server_ca3_key, GNUTLS_X509_FMT_PEM));
   169	
   170		for (round = 0; round < 2; round++) {
   171			cache_hits = 0;
   172	
   173			ret = socketpair(AF_UNIX, SOCK_STREAM, 0, fd);
   174			if (ret < 0) {
   175				perror("socketpair");
   176				exit(1);
   177			}
   178	
   179			child = fork();
   180			if (child < 0) {
   181				perror("fork");
   182				exit(1);
   183			}
   184	
   185			if (child == 0) {
   186				close(fd[0]);
   187				client(fd[1]);
   188				exit(0);
   189			}
   190	
   191			close(fd[1]);
   192			server(fd[0], server_cred);
   193	
   194			if (round == 0 && cache_hits != 0)
   195				fail("server: cache hit before the cache was populated\n");
   196			if (round == 1 && cache_hits == 0)
   197				fail("server: compressed certificate cache was not used\n");
   198	
   199			waitpid(child, &ret, 0);
   200			check_wait_status(ret);
   201		}
   202	
   203		gnutls_certificate_free_credentials(server_cred);
   204		gnutls_global_deinit();
   205	}
